// `o[k](...)` reaches String and Number methods, and answers what the DOT
// spelling answers.
//
// Every row is printed TWICE -- once through `s[k]()`, once through
// `s.m()` -- from the SAME receiver in the SAME call, so the two spellings
// are compared inside the program rather than across two runs of a
// harness. A row prints `<elem> | <dot>` and the two halves must be equal;
// where they are not, the row says so in its own output.
//
// The whole file is then byte-compared against Node v25.9.0. That is the
// deliverable: not that some fence moved, but that a compiled binary and
// Node print the same bytes.
//
// WHY THIS IS NOT A RECEIVER-BINDING FIXTURE. Measured before the change:
// `typeof s[k]` was `undefined` where Node says `function`. The member
// never resolved, so there was no `this` to drop and no ambient window
// involved. That is what separates this from the object-literal receiver
// gap pinned as 4113, where the member DOES resolve, the call DOES run,
// and only the receiver is wrong. Two gaps, two mechanisms, one grid each.
"use strict";
function t(f) { try { return String(f()); } catch (e) { return "THREW " + String(e && e.message); } }

// Keys held in module-scope `var`s, the way protobufjs holds the `toLong`/
// `toNumber` key that started all of this. Nothing here is a literal in
// subscript position, so a constant-folder cannot turn these into the dot
// spelling behind the measurement's back.
var UP = "toUpperCase", LO = "toLowerCase", TR = "trim", TS = "trimStart", TE = "trimEnd";
var CA = "charAt", CC = "charCodeAt", SW = "startsWith", EW = "endsWith";
var SB = "substring", RP = "repeat", PS = "padStart", PE = "padEnd";
var STS = "toString", VO = "valueOf", SPL = "split";
var NTS = "toString", NFX = "toFixed";

// Checked-dynamic receivers: JSON.parse-derived, so they lower to the dyn
// tree and reach the runtime dispatch rather than a static intrinsic.
function ds() { return JSON.parse('"  aBc  "'); }
function dp() { return JSON.parse('"ab"'); }
function dn() { return JSON.parse("5"); }
function dbig() { return JSON.parse("255"); }
function dfrac() { return JSON.parse("1.5"); }
function dbool() { return JSON.parse("true"); }

// Each row: the element spelling, then the dot twin, then a verdict the
// program computes itself so a reader does not have to compare columns.
function pair(elem, dot) {
  // `let`, not `var`: a `var` read twice in a provenance JS module trips
  // SC9001 "assign to undeclared local/global" on main today (minimal repro
  // in the block/recv report). Unrelated to this fixture's subject.
  let a = t(elem);
  let b = t(dot);
  return a + " | " + b + " | " + (a === b ? "SAME" : "DIFFER");
}

exports.rUpper = function () { var s = dp(); return pair(function () { return s[UP](); }, function () { return s.toUpperCase(); }); };
exports.rLower = function () { var s = JSON.parse('"AB"'); return pair(function () { return s[LO](); }, function () { return s.toLowerCase(); }); };
exports.rTrim = function () { var s = ds(); return pair(function () { return "[" + s[TR]() + "]"; }, function () { return "[" + s.trim() + "]"; }); };
exports.rTrimStart = function () { var s = ds(); return pair(function () { return "[" + s[TS]() + "]"; }, function () { return "[" + s.trimStart() + "]"; }); };
exports.rTrimEnd = function () { var s = ds(); return pair(function () { return "[" + s[TE]() + "]"; }, function () { return "[" + s.trimEnd() + "]"; }); };
exports.rCharAt = function () { var s = dp(); return pair(function () { return s[CA](1); }, function () { return s.charAt(1); }); };
exports.rCharAtOob = function () { var s = dp(); return pair(function () { return "[" + s[CA](9) + "]"; }, function () { return "[" + s.charAt(9) + "]"; }); };
exports.rCharCodeAt = function () { var s = dp(); return pair(function () { return s[CC](0); }, function () { return s.charCodeAt(0); }); };
exports.rCharCodeOob = function () { var s = dp(); return pair(function () { return s[CC](9); }, function () { return s.charCodeAt(9); }); };
exports.rStartsWith = function () { var s = dp(); return pair(function () { return s[SW]("a"); }, function () { return s.startsWith("a"); }); };
exports.rStartsWithNo = function () { var s = dp(); return pair(function () { return s[SW]("b"); }, function () { return s.startsWith("b"); }); };
exports.rEndsWith = function () { var s = dp(); return pair(function () { return s[EW]("b"); }, function () { return s.endsWith("b"); }); };
exports.rSubstring = function () { var s = JSON.parse('"abcdef"'); return pair(function () { return s[SB](1, 4); }, function () { return s.substring(1, 4); }); };
exports.rSubstringOne = function () { var s = JSON.parse('"abcdef"'); return pair(function () { return s[SB](2); }, function () { return s.substring(2); }); };
exports.rRepeat = function () { var s = dp(); return pair(function () { return s[RP](3); }, function () { return s.repeat(3); }); };
exports.rRepeatZero = function () { var s = dp(); return pair(function () { return "[" + s[RP](0) + "]"; }, function () { return "[" + s.repeat(0) + "]"; }); };
exports.rPadStart = function () { var s = dp(); return pair(function () { return "[" + s[PS](5) + "]"; }, function () { return "[" + s.padStart(5) + "]"; }); };
exports.rPadStartFill = function () { var s = dp(); return pair(function () { return s[PS](5, "xy"); }, function () { return s.padStart(5, "xy"); }); };
exports.rPadEnd = function () { var s = dp(); return pair(function () { return "[" + s[PE](5) + "]"; }, function () { return "[" + s.padEnd(5) + "]"; }); };
exports.rStrToString = function () { var s = dp(); return pair(function () { return s[STS](); }, function () { return s.toString(); }); };
exports.rStrValueOf = function () { var s = dp(); return pair(function () { return s[VO](); }, function () { return s.valueOf(); }); };

// NUMBER receivers.
exports.rNumToString = function () { var n = dn(); return pair(function () { return n[NTS](); }, function () { return n.toString(); }); };
exports.rNumRadix2 = function () { var n = dn(); return pair(function () { return n[NTS](2); }, function () { return n.toString(2); }); };
exports.rNumRadix16 = function () { var n = dbig(); return pair(function () { return n[NTS](16); }, function () { return n.toString(16); }); };
exports.rNumRadix36 = function () { var n = dbig(); return pair(function () { return n[NTS](36); }, function () { return n.toString(36); }); };
exports.rFracToString = function () { var n = dfrac(); return pair(function () { return n[NTS](); }, function () { return n.toString(); }); };
exports.rNumValueOf = function () { var n = dn(); return pair(function () { return n[VO](); }, function () { return n.valueOf(); }); };

// THE REFUSALS, pinned so they cannot drift into a lie again. The element
// spelling does NOT reimplement the names the dot spelling reaches through
// the regex tables; it fences them by name. `is not a function` would be
// false here -- Node has split -- and the pin exists to keep it false.
exports.rSplitFenced = function () { var s = dp(); return t(function () { return s[SPL](""); }); };
exports.rToFixedFenced = function () { var n = dfrac(); return t(function () { return n[NFX](2); }); };
// The dot twins of the two rows above, so the pin records BOTH spellings.
exports.rSplitDot = function () { var s = dp(); return t(function () { return s.split(""); }); };
exports.rToFixedDot = function () { var n = dfrac(); return t(function () { return n.toFixed(2); }); };
// A name no prototype has: Node's own "is not a function", still true.
exports.rTrulyMissing = function () { var s = dp(); return t(function () { return s["nope"](); }); };
// Object.prototype still reachable underneath the new arms -- the control
// that says these arms were INSERTED into the chain, not laid over it.
exports.rStrHasOwn = function () { var s = dp(); return t(function () { return s["hasOwnProperty"]("length"); }); };
exports.rNumHasOwn = function () { var n = dn(); return t(function () { return n["hasOwnProperty"]("x"); }); };
// A BOOLEAN receiver, which had no arm either.
exports.rBoolToString = function () { var b = dbool(); return pair(function () { return b[STS](); }, function () { return b.toString(); }); };
